import { atom, read, update } from 'claude-code'
import type { EngineInterface, ModelUsage, Register } from 'claude-code'

import type { Activity, Tokens, Turn } from '../types'

// Low, central, high.
type Band = [number, number, number]

// --- Calibration -------------------------------------------------------------
// Anthropic publishes no energy, hardware or region data, so every factor is
// taken from production measurements or models of comparable frontier systems.
// The activity is stored raw: change a factor and everything recalculates.

// Facility electricity per token of a frontier-scale model (>200B parameters).
// Watershed Activity Tier, hyperscaler defaults (Bistline et al. 2026,
// "Estimating GHG Emissions from AI Use", Table 2): EI_in 0.32 and EI_out
// 0.96 Wh per 1,000 tokens, times PUE 1.10, derived from Google's measured
// 0.24 Wh median Gemini prompt (Elsworth et al. 2025, arXiv 2508.15734, which
// counts accelerators, host CPU/DRAM, idle capacity and overhead). Oviedo et al.
// (2026, arXiv 2509.20241) reach the same ~1 Wh per 1,000 output tokens bottom-up
// for >200B models on H100 (0.31 Wh for a 300-token answer); their IQR,
// 0.16-0.60 Wh, sets the x0.5-x2 band, which is also Hausfather's (2026) "factor
// of ~2 in either direction". Thinking is billed as output, so reasoning effort
// acts through output tokens. Cache writes are a prefill, so they count as input.
const WH_PER_TOKEN = { input: 0.32e-3, output: 0.96e-3 }
const SPREAD: Band = [0.5, 1, 2]
const PUE = 1.1

// A cache read skips the prefill; what remains (KV transfer and attention over
// the cached context) has not been measured anywhere. Convention: 10% of fresh
// input, the API price ratio, bounded at 1% and 25% (Hausfather 2026, "The real
// energy use of agentic AI"; Couch 2026). It drives most of an agentic session.
const CACHE_READ: Band = [0.01, 0.1, 0.25]

// Haiku-class models use roughly 5-7x less energy per token than frontier ones
// (Hausfather 2026, footnote 5); every other Claude model counts as frontier.
const TIERS: [RegExp, number][] = [[/haiku/, 1 / 6]]

// Operational water (consumption, not withdrawal) per facility Wh: on-site
// cooling WUE / PUE + the grid's water intensity (EWIF), as in Li et al. (2025,
// CACM, arXiv 2304.03271, Table 1). On-site: AWS 0.12 L/kWh (2025), US average
// 0.55, Google 1.15 (Elsworth et al. 2025). Grid: Texas 1.29, US average 3.14,
// Washington 9.50 L/kWh (Li et al. Table 1).
const WUE_SITE: Band = [0.12, 0.55, 1.15]
const EWIF: Band = [1.29, 3.14, 9.5]

// Incremental power while a tool runs, local CPU or remote server: judgement,
// counted with the same PUE and water. Negligible next to inference.
// ponytail: wall time x power overcounts tools that mostly wait on the network.
const TOOL_WATTS: Band = [2, 6, 20]
// Tools whose wall time is waiting, not work (a subagent's own steps are counted).
const WAITS = new Set(['Agent', 'Task', 'AskUserQuestion', 'ScheduleWakeup', 'Monitor', 'SendMessage', 'EnterPlanMode', 'ExitPlanMode'])

// Fixed decade bands on the central estimate, so the glyphs compare across
// turns and sessions. One glyph per band reached.
const WH_BANDS = [1, 10, 100, 1000]
const ML_BANDS = [5, 50, 500, 5000]
// -----------------------------------------------------------------------------

const PANE = 'footprint'
const EMPTY: Activity = { models: {}, tools: {} }
const session = atom({ plugin: 'footprint', key: 'session' } as const, EMPTY)
const turn = atom({ plugin: 'footprint', key: 'turn' } as const, EMPTY)
const turns = atom({ plugin: 'footprint', key: 'turns' } as const, [] as Turn[])
const isBackfilled = atom({ plugin: 'footprint', key: 'isBackfilled' } as const, false)
const isPartial = atom({ plugin: 'footprint', key: 'isPartial' } as const, false)

const band = (f: (i: 0 | 1 | 2) => number): Band => [f(0), f(1), f(2)]
const tier = (model: string) => TIERS.find(([re]) => re.test(model))?.[1] ?? 1

export const impact = (models: Activity['models'], toolMs: number) => {
  const wh = band(i => {
    const inference = Object.entries(models).reduce(
      (sum, [key, t]) =>
        sum +
        tier(key) *
          SPREAD[i] *
          ((t.input + t.cacheWrite + t.cacheRead * CACHE_READ[i]) * WH_PER_TOKEN.input + t.output * WH_PER_TOKEN.output),
      0,
    )

    return (inference + (toolMs / 3.6e6) * TOOL_WATTS[i]) * PUE
  })

  return { wh, ml: band(i => wh[i] * (WUE_SITE[i] / PUE + EWIF[i])) }
}

const toolMs = (a: Activity) => Object.values(a.tools).reduce((sum, t) => sum + t.ms, 0)
const isEmpty = (a: Activity) => Object.keys(a.models).length === 0 && Object.keys(a.tools).length === 0

export const level = (central: number, bands: number[]) => 1 + bands.filter(b => central >= b).length
const sig = (x: number) => String(Number(x.toPrecision(2)))
const count = (n: number) => (n >= 1e6 ? `${sig(n / 1e6)}M` : n >= 1e3 ? `${sig(n / 1e3)}k` : String(n))
const unit = (x: number, small: string, big: string) => (x >= 1000 ? `${sig(x / 1000)} ${big}` : `${sig(x)} ${small}`)
const span = ([lo, , hi]: Band, small: string, big: string) =>
  hi >= 1000 ? `${sig(lo / 1000)}–${sig(hi / 1000)} ${big}` : `${sig(lo)}–${sig(hi)} ${small}`
const energy = (b: Band) => `${'⚡'.repeat(level(b[1], WH_BANDS))} ${unit(b[1], 'Wh', 'kWh')}`
const water = (b: Band) => `${'💧'.repeat(level(b[1], ML_BANDS))} ${unit(b[1], 'mL', 'L')}`

// The one-glance form every line uses: central estimates, a glyph per decade.
export const glance = (a: Activity) => {
  const { wh, ml } = impact(a.models, toolMs(a))

  return `${energy(wh)} ${water(ml)}`
}

const addTokens = (key: string, u: ModelUsage) => (a: Activity): Activity => {
  const t = a.models[key] ?? { steps: 0, input: 0, cacheWrite: 0, cacheRead: 0, output: 0 }
  const next: Tokens = {
    steps: t.steps + 1,
    input: t.input + u.input_tokens,
    cacheWrite: t.cacheWrite + u.cache_creation_input_tokens,
    cacheRead: t.cacheRead + u.cache_read_input_tokens,
    output: t.output + u.output_tokens,
  }

  return { ...a, models: { ...a.models, [key]: next } }
}

const addTool = (tool: string, ms: number) => (a: Activity): Activity => {
  const t = a.tools[tool] ?? { calls: 0, ms: 0 }

  return { ...a, tools: { ...a.tools, [tool]: { calls: t.calls + 1, ms: t.ms + ms } } }
}

const record = async ($: EngineInterface, fn: (a: Activity) => Activity) => {
  await update($, session, fn)
  await update($, turn, fn)
}

type Block = { type?: string; id?: string; name?: string; tool_use_id?: string }
type Row = {
  type?: string
  subtype?: string
  durationMs?: number
  timestamp?: string
  message?: { id?: string; model?: string; usage?: ModelUsage; content?: unknown }
}

// Rebuilds the session from its transcript files (main and subagents), split
// into turns at each turn_duration row, so the meter covers what happened
// before the mod loaded and after a --resume. Effort is not in the transcript.
export const fromTranscript = (texts: string[]) => {
  const rows = texts
    .flatMap(text => text.split('\n'))
    .filter(line => line.includes('"usage"') || line.includes('"tool_result"') || line.includes('"turn_duration"'))
    .flatMap(line => {
      try {
        return [JSON.parse(line) as Row]
      } catch {
        return []
      }
    })
    .sort((a, b) => (a.timestamp ?? '').localeCompare(b.timestamp ?? ''))
  let all = EMPTY
  let current = EMPTY
  const done: Turn[] = []
  const seen = new Set<string>()
  const started = new Map<string, { tool: string; at: number }>()
  const apply = (fn: (a: Activity) => Activity) => {
    all = fn(all)
    current = fn(current)
  }

  for (const row of rows) {
    const at = Date.parse(row.timestamp ?? '')
    const blocks = Array.isArray(row.message?.content) ? (row.message.content as Block[]) : []
    if (row.subtype === 'turn_duration' && row.durationMs !== undefined) {
      done.push({ durationMs: row.durationMs, activity: current })
      current = EMPTY
    }
    const m = row.message
    if (row.type === 'assistant' && m?.usage && m.id && m.model !== '<synthetic>' && !seen.has(m.id)) {
      seen.add(m.id)
      apply(addTokens(`${m.model}|earlier`, m.usage))
    }
    for (const b of blocks) {
      if (b.type === 'tool_use' && b.id && b.name) started.set(b.id, { tool: b.name, at })
      const call = b.type === 'tool_result' && b.tool_use_id ? started.get(b.tool_use_id) : undefined
      if (call) apply(addTool(call.tool, WAITS.has(call.tool) ? 0 : Math.max(0, at - call.at)))
    }
  }

  return { session: all, turn: current, turns: done }
}

const backfill = async ($: EngineInterface) => {
  try {
    const home = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${await $.env.get('HOME')}/.claude`
    const project = `${home}/projects/${(await $.session.cwd()).replace(/[^a-zA-Z0-9]/g, '-')}`
    const id = await $.session.id()
    const subagents = await $.fs.list(`${project}/${id}/subagents`).catch(() => [])
    // ponytail: $.fs.read stops at 4 MiB per file; a longer session counts from load.
    const texts = await Promise.all([
      $.fs.read(`${project}/${id}.jsonl`),
      ...subagents.filter(f => f.name.endsWith('.jsonl')).map(f => $.fs.read(`${project}/${id}/subagents/${f.name}`)),
    ])
    const found = fromTranscript(texts)
    await update($, session, () => found.session)
    await update($, turn, () => found.turn)
    await update($, turns, () => found.turns)
  } catch {
    await update($, isPartial, () => true)
  }
  await update($, isBackfilled, () => true)
}

const openPane = async ($: EngineInterface) => {
  const all = await read($, session)
  await $.ui.open({ id: PANE, title: 'Footprint', rows: 10 + Object.keys(all.models).length, focus: true, closeOnEscape: true })
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'footprint',
      description: 'Estimated electricity and water of this session, by model and tool',
    })
    if (!(await read($, isBackfilled))) await backfill($)

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, session, () => EMPTY)
      await update($, turn, () => EMPTY)
      await update($, turns, () => [])
      await update($, isPartial, () => false)
    }

    return next(e)
  })

  on('command.run', { command: 'footprint' }, async $ => {
    await openPane($)

    return { text: 'Footprint opened.' }
  })

  on('prompt.submit', async ($, e, next) => {
    await update($, turn, () => EMPTY)

    return next(e)
  })

  // Every model request of the session, main loop and subagents alike.
  on('turn.step', async function* ($, e, next) {
    const step = yield* next(e)
    if (step.usage) await record($, addTokens(`${step.usage.model}|${e.effort ?? 'default'}`, step.usage))

    return step
  })

  // Side calls other mods make (a Haiku naming call, say).
  on('model.complete', async ($, e, next) => {
    const done = await next(e)
    if (done.value) await record($, addTokens(`${e.model}|${e.effort ?? 'default'}`, done.value.usage))

    return done
  })

  on('tool.call', async ($, e, next) => {
    const startedAt = await $.clock.now()
    const ran = await next(e)
    const ms = WAITS.has(e.tool) ? 0 : (await $.clock.now()) - startedAt
    await record($, addTool(e.tool, ms))

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      const activity = await read($, turn)
      await update($, turns, list => [...list, { durationMs: e.durationMs, activity }].slice(-200))
    }

    return next(e)
  })

  // Live, beside the engine's own time and tokens: "Pondering… ⚡ 0.4 Wh 💧 1.7 mL (12s · ↓ 300 tokens)".
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const now = await read($, turn)

    return isEmpty(now) ? next(e) : next({ ...e, props: { ...e.props, suffix: `${e.props.suffix} ${glance(now)}` } })
  })

  // Each turn's closing line: "✻ ⚡⚡ 3.1 Wh 💧💧 13 mL · Baked for 5m 48s".
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    const list = await read($, turns)
    const ms = e.props.durationMs
    const hit = list.find(t => t.durationMs === ms) ?? list.find(t => Math.abs(t.durationMs - ms) < 1000)

    return hit && !isEmpty(hit.activity)
      ? next({ ...e, props: { ...e.props, word: `${glance(hit.activity)} · ${e.props.word}` } })
      : next(e)
  })

  // The session so far, dim at the end of the hint line under the prompt.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const all = await read($, session)

    return isEmpty(all) ? next(e) : next({ ...e, props: { ...e.props, tail: `${glance(all)} this session` } })
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const all = await read($, session)
    const now = await read($, turn)
    const central = impact(all.models, toolMs(all)).wh[1]
    const share = (b: Band) => (central > 0 ? `${Math.round((100 * b[1]) / central)}%` : '')
    const cells = (widths: number[], parts: string[], dim: boolean[] = []) => (
      <Box flexDirection="row">
        {parts.map((part, i) => (
          <Box width={widths[i] ?? 10}>
            <Text dimColor={dim[i] ?? false} wrap="truncate">
              {part}
            </Text>
          </Box>
        ))}
      </Box>
    )
    const total = (label: string, a: Activity) => {
      const { wh, ml } = impact(a.models, toolMs(a))

      return cells([9, 15, 15, 15, 16], [label, energy(wh), span(wh, 'Wh', 'kWh'), water(ml), span(ml, 'mL', 'L')], [false, false, true, false, true])
    }
    const ROW = [26, 46, 9, 6]
    const models = Object.entries(all.models).sort(([a, x], [b, y]) => impact({ [b]: y }, 0).wh[1] - impact({ [a]: x }, 0).wh[1])
    const tools = Object.entries(all.tools).sort(([, a], [, b]) => b.calls - a.calls)
    const toolWh = impact({}, toolMs(all)).wh

    return (
      <Box flexDirection="column">
        {total('Session', all)}
        {total('Turn', now)}
        <Text> </Text>
        {models.map(([key, t]) => {
          const [model = key, effort = ''] = key.split('|')
          const wh = impact({ [key]: t }, 0).wh

          return cells(
            ROW,
            [
              `${model.replace(/^claude-/, '')} · ${effort}`,
              `${t.steps} steps · out ${count(t.output)} · cache ${count(t.cacheRead + t.cacheWrite)} · in ${count(t.input)}`,
              unit(wh[1], 'Wh', 'kWh'),
              share(wh),
            ],
            [false, true, false, true],
          )
        })}
        {tools.length > 0 &&
          cells(
            ROW,
            [
              'tools',
              tools
                .slice(0, 5)
                .map(([tool, t]) => `${tool.replace(/^mcp__/, '')} ${t.calls}`)
                .join(' · '),
              unit(toolWh[1], 'Wh', 'kWh'),
              share(toolWh),
            ],
            [false, true, false, true],
          )}
        <Text> </Text>
        <Text dimColor wrap="wrap">
          Per token: Watershed (2026) factors from Google's measured 0.24 Wh prompt, matching Oviedo et al. (2026) for
          {'>'}200B models; ranges ×0.5–×2. Cache reads at 10% (1–25%) of fresh input, an unmeasured convention (Hausfather
          2026). Water: on-site cooling plus electricity generation (Li et al. 2025). Haiku at 1/6.
          {(await read($, isPartial)) ? ' Counting since the mod loaded: the transcript was too long to read.' : ''}
        </Text>
      </Box>
    )
  })
}

