// Raw activity only: the impact is computed from it at display time, so new
// coefficients recalculate everything already recorded.
export type Tokens = { steps: number; input: number; cacheWrite: number; cacheRead: number; output: number }
export type ToolUse = { calls: number; ms: number }
export type Activity = {
  // keyed `${model}|${effort}`
  models: Record<string, Tokens>
  tools: Record<string, ToolUse>
}
// A finished main-loop turn, keyed by the duration its "Baked for" line shows.
export type Turn = { durationMs: number; activity: Activity }

declare module 'claude-code' {
  interface PluginState {
    footprint: { session: Activity; turn: Activity; turns: Turn[]; isBackfilled: boolean; isPartial: boolean }
  }
}
